SELECT ?zone ?sensor ?tsid WHERE {
  ?zone brick:hasSubclassOf brick:Zone .
  ?zone rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "Perimeter_mid_ZN_3"))
  ?p brick:hasParentLocation ?zone ; filter(?sensor) .
}

SELECT DISTINCT ?class WHERE {
  ?p a ?class .
  FILTER(?class != rdf:Property)
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?sensor ?sensorname ?zoneid ?tsid ?sensorid WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?zoneid .
  FILTER(CONTAINS(?zoneid, "Perimeter_mid_ZN_3"))
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:hasPropertySensor ?zone .
  ?sensor rdfs:label ?sensorname .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid . }
  OPTIONAL { ?sensor ref:hasIFCReference ?sensorid . }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?p WHERE {
  ?p a brick:Electric_Power_Sensor .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?z WHERE {
  ?z a brick:HVAC_Zone .
}

SELECT DISTINCT ?n WHERE {
  ?n ?p ?o .
  FILTER(CONTAINS(STR(?n), "mid") || CONTAINS(STR(?n), "ZN") || CONTAINS(STR(?n), "Perimeter") || CONTAINS(STR(?n), "Core"))
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?z ?b WHERE {
  ?b a brick:Building .
  ?z a brick:HVAC_Zone .
  ?z brick:hasParentLocation ?b .
} LIMIT 30

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?z ?lbl WHERE {
  ?z rdfs:label ?lbl .
}

